  "sojusz_wojskowy" /* SojuszWojskowy */,
  "sojusz_defensywny",
  "sojusz_pelny",
  "otwarte_granice" /* OtwartGranice */,
  "prawo_wojskowe_przemarszu" /* PrawoWojskowePrzemarszu */,
  "umowa_handlowa" /* UmowaHandlowa */
